-- 0005 Media: assets (immutable originals), derived variants, upload sessions and parts, and
-- rights grants (first-party ownership declarations in M1; licences/creator permissions in M2).
--
-- Object keys are generated by the server (ws/<workspace>/assets/<asset>/v<version>/...),
-- never by clients. Database rows hold metadata only; bytes live in private object storage.

CREATE TABLE media_assets (
  id                 uuid PRIMARY KEY,
  workspace_id       uuid NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  page_id            uuid NOT NULL,
  kind               text NOT NULL CHECK (kind IN ('video', 'image')),
  status             text NOT NULL CHECK (status IN ('uploading', 'validating', 'ready', 'rejected', 'deleted')),
  origin             text NOT NULL DEFAULT 'upload' CHECK (origin IN ('upload', 'render', 'import')),
  version            integer NOT NULL DEFAULT 1 CHECK (version > 0),
  original_filename  text NOT NULL CHECK (length(original_filename) BETWEEN 1 AND 120),
  declared_mime      text NOT NULL CHECK (length(declared_mime) <= 100),
  detected_container text CHECK (length(detected_container) <= 20),
  size_bytes         bigint NOT NULL CHECK (size_bytes > 0),
  sha256             text CHECK (sha256 ~ '^[0-9a-f]{64}$'),
  object_key         text NOT NULL UNIQUE CHECK (object_key ~ '^ws/[0-9a-f-]{36}/assets/[0-9a-f-]{36}/v[0-9]+/'),
  object_version_id  text CHECK (length(object_version_id) <= 1024),
  object_etag        text CHECK (length(object_etag) <= 200),
  width              integer CHECK (width > 0),
  height             integer CHECK (height > 0),
  duration_ms        integer CHECK (duration_ms > 0),
  has_audio          boolean,
  video_codec        text,
  audio_codec        text,
  frame_rate         numeric(8, 3),
  rotation           smallint CHECK (rotation IN (0, 90, 180, 270)),
  pix_fmt            text,
  probe              jsonb CHECK (probe IS NULL OR pg_column_size(probe) < 16384),
  ffprobe_version    text,
  rejection_code     text CHECK (length(rejection_code) <= 60),
  rejection_detail   text CHECK (length(rejection_detail) <= 500),
  is_sample          boolean NOT NULL DEFAULT false,
  rights_version     integer NOT NULL DEFAULT 0 CHECK (rights_version >= 0),
  created_by         uuid NOT NULL REFERENCES users (id),
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  validated_at       timestamptz,
  deleted_at         timestamptz,
  UNIQUE (workspace_id, id),
  FOREIGN KEY (workspace_id, page_id) REFERENCES pages (workspace_id, id) ON DELETE CASCADE,
  CHECK (status <> 'ready' OR (sha256 IS NOT NULL AND width IS NOT NULL AND height IS NOT NULL
                               AND validated_at IS NOT NULL)),
  CHECK (status <> 'rejected' OR rejection_code IS NOT NULL)
);
CREATE INDEX media_assets_page_idx ON media_assets (workspace_id, page_id, created_at DESC, id DESC);
CREATE TRIGGER media_assets_touch BEFORE UPDATE ON media_assets
  FOR EACH ROW EXECUTE FUNCTION relay_touch_updated_at();

-- Lifecycle and immutability guard: validated originals can never be repointed or rewritten.
CREATE FUNCTION relay_media_asset_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW.workspace_id <> OLD.workspace_id OR NEW.object_key <> OLD.object_key
     OR NEW.kind <> OLD.kind OR NEW.version <> OLD.version OR NEW.page_id <> OLD.page_id THEN
    RAISE EXCEPTION 'media asset identity is immutable' USING ERRCODE = 'P0001';
  END IF;
  IF OLD.status IN ('ready', 'rejected', 'deleted') AND (
       NEW.sha256 IS DISTINCT FROM OLD.sha256 OR NEW.size_bytes <> OLD.size_bytes
       OR NEW.object_version_id IS DISTINCT FROM OLD.object_version_id
       OR NEW.object_etag IS DISTINCT FROM OLD.object_etag
       OR NEW.width IS DISTINCT FROM OLD.width OR NEW.height IS DISTINCT FROM OLD.height
       OR NEW.duration_ms IS DISTINCT FROM OLD.duration_ms) THEN
    RAISE EXCEPTION 'validated media is immutable; upload a new asset instead' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status <> OLD.status AND NOT (
       (OLD.status = 'uploading'  AND NEW.status IN ('validating', 'rejected', 'deleted')) OR
       (OLD.status = 'validating' AND NEW.status IN ('ready', 'rejected', 'deleted')) OR
       (OLD.status = 'ready'      AND NEW.status = 'deleted') OR
       (OLD.status = 'rejected'   AND NEW.status = 'deleted')) THEN
    RAISE EXCEPTION 'invalid media status transition % -> %', OLD.status, NEW.status USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END
$$;
CREATE TRIGGER media_assets_guard BEFORE UPDATE ON media_assets
  FOR EACH ROW EXECUTE FUNCTION relay_media_asset_guard();

CREATE TABLE media_variants (
  id                uuid PRIMARY KEY,
  workspace_id      uuid NOT NULL,
  asset_id          uuid NOT NULL,
  kind              text NOT NULL CHECK (kind IN ('thumbnail', 'poster', 'proxy')),
  profile           text NOT NULL CHECK (length(profile) BETWEEN 1 AND 60),
  object_key        text NOT NULL UNIQUE,
  object_version_id text,
  mime              text NOT NULL,
  width             integer CHECK (width > 0),
  height            integer CHECK (height > 0),
  duration_ms       integer,
  size_bytes        bigint NOT NULL CHECK (size_bytes > 0),
  renderer_version  text NOT NULL,
  created_at        timestamptz NOT NULL DEFAULT now(),
  UNIQUE (asset_id, kind, profile),
  UNIQUE (workspace_id, id),
  FOREIGN KEY (workspace_id, asset_id) REFERENCES media_assets (workspace_id, id) ON DELETE CASCADE
);

CREATE TABLE upload_sessions (
  id                      uuid PRIMARY KEY,
  workspace_id            uuid NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE,
  asset_id                uuid NOT NULL UNIQUE,
  page_id                 uuid NOT NULL,
  created_by              uuid NOT NULL REFERENCES users (id),
  strategy                text NOT NULL CHECK (strategy IN ('single', 'multipart')),
  status                  text NOT NULL CHECK (status IN ('pending', 'completing', 'completed', 'aborted', 'expired', 'failed')),
  object_key              text NOT NULL,
  s3_upload_id            text CHECK (length(s3_upload_id) <= 1024),
  declared_mime           text NOT NULL,
  declared_size           bigint NOT NULL CHECK (declared_size > 0),
  checksum_sha256         text,
  part_size               bigint CHECK (part_size > 0),
  part_count              integer CHECK (part_count BETWEEN 1 AND 10000),
  reserved_bytes          bigint NOT NULL CHECK (reserved_bytes >= 0),
  reservation_released_at timestamptz,
  expires_at              timestamptz NOT NULL,
  completed_at            timestamptz,
  ended_at                timestamptz,
  failure_code            text CHECK (length(failure_code) <= 60),
  created_at              timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now(),
  UNIQUE (workspace_id, id),
  FOREIGN KEY (workspace_id, asset_id) REFERENCES media_assets (workspace_id, id) ON DELETE CASCADE,
  FOREIGN KEY (workspace_id, page_id) REFERENCES pages (workspace_id, id) ON DELETE CASCADE,
  CHECK ((strategy = 'multipart') = (s3_upload_id IS NOT NULL)),
  CHECK (strategy = 'single' OR (part_size IS NOT NULL AND part_count IS NOT NULL))
);
CREATE INDEX upload_sessions_open_expiry_idx ON upload_sessions (expires_at)
  WHERE status IN ('pending', 'completing');
CREATE INDEX upload_sessions_reserved_idx ON upload_sessions (workspace_id)
  WHERE reservation_released_at IS NULL;
CREATE TRIGGER upload_sessions_touch BEFORE UPDATE ON upload_sessions
  FOR EACH ROW EXECUTE FUNCTION relay_touch_updated_at();

-- Server-generated part plan; etag/size are filled from the storage provider's ListParts,
-- never from client claims alone. Multipart ETags are not content hashes.
CREATE TABLE upload_session_parts (
  workspace_id      uuid NOT NULL,
  upload_session_id uuid NOT NULL,
  part_number       integer NOT NULL CHECK (part_number BETWEEN 1 AND 10000),
  expected_size     bigint NOT NULL CHECK (expected_size > 0),
  signed_count      integer NOT NULL DEFAULT 0 CHECK (signed_count >= 0),
  last_signed_at    timestamptz,
  etag              text,
  size_bytes        bigint,
  verified_at       timestamptz,
  PRIMARY KEY (upload_session_id, part_number),
  FOREIGN KEY (workspace_id, upload_session_id) REFERENCES upload_sessions (workspace_id, id) ON DELETE CASCADE
);

CREATE TABLE source_rights_grants (
  id                 uuid PRIMARY KEY,
  workspace_id       uuid NOT NULL,
  asset_id           uuid NOT NULL,
  grant_type         text NOT NULL CHECK (grant_type IN ('first_party_declaration', 'license', 'creator_permission')),
  grantor_user_id    uuid REFERENCES users (id),
  grantor_name       text CHECK (length(grantor_name) <= 200),
  statement_version  text CHECK (length(statement_version) <= 40),
  statement          text CHECK (length(statement) <= 2000),
  evidence_pointer   text CHECK (length(evidence_pointer) <= 500),
  can_view           boolean NOT NULL,
  can_edit           boolean NOT NULL,
  can_export         boolean NOT NULL,
  can_publish        boolean NOT NULL,
  can_commercial_use boolean NOT NULL,
  -- NULL means every destination provider is permitted.
  permitted_providers text[],
  valid_from         timestamptz NOT NULL DEFAULT now(),
  valid_until        timestamptz,
  version            integer NOT NULL DEFAULT 1 CHECK (version > 0),
  revoked_at         timestamptz,
  revoked_by         uuid REFERENCES users (id),
  revoke_reason      text CHECK (length(revoke_reason) <= 500),
  created_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (workspace_id, id),
  FOREIGN KEY (workspace_id, asset_id) REFERENCES media_assets (workspace_id, id) ON DELETE CASCADE,
  CHECK (valid_until IS NULL OR valid_until > valid_from),
  CHECK (grant_type <> 'first_party_declaration' OR grantor_user_id IS NOT NULL)
);
CREATE INDEX source_rights_grants_asset_idx ON source_rights_grants (workspace_id, asset_id);

-- Any change to an asset's rights bumps its rights_version so approvals and intents that
-- captured an older version become stale.
CREATE FUNCTION relay_bump_rights_version() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  UPDATE media_assets SET rights_version = rights_version + 1
   WHERE workspace_id = NEW.workspace_id AND id = NEW.asset_id;
  RETURN NULL;
END
$$;
CREATE TRIGGER source_rights_grants_bump AFTER INSERT OR UPDATE ON source_rights_grants
  FOR EACH ROW EXECUTE FUNCTION relay_bump_rights_version();

SELECT relay_apply_tenant_rls('media_assets');
SELECT relay_apply_tenant_rls('media_variants');
SELECT relay_apply_tenant_rls('upload_sessions');
SELECT relay_apply_tenant_rls('upload_session_parts');
SELECT relay_apply_tenant_rls('source_rights_grants');
SELECT relay_apply_maintenance_scan('upload_sessions');

GRANT SELECT, INSERT ON media_assets TO relay_app;
GRANT UPDATE (status, object_version_id, object_etag, rejection_code, rejection_detail, rights_version,
              updated_at, deleted_at)
  ON media_assets TO relay_app;
GRANT SELECT ON media_assets TO relay_worker;
GRANT UPDATE (status, detected_container, sha256, object_version_id, object_etag, width, height, duration_ms,
              has_audio, video_codec, audio_codec, frame_rate, rotation, pix_fmt, probe, ffprobe_version,
              rejection_code, rejection_detail, updated_at, validated_at, deleted_at)
  ON media_assets TO relay_worker;

GRANT SELECT ON media_variants TO relay_app;
GRANT SELECT, INSERT ON media_variants TO relay_worker;

GRANT SELECT, INSERT ON upload_sessions TO relay_app;
GRANT UPDATE (status, reservation_released_at, completed_at, ended_at, failure_code, updated_at)
  ON upload_sessions TO relay_app;
GRANT SELECT ON upload_sessions TO relay_worker;
GRANT UPDATE (status, reservation_released_at, ended_at, failure_code, updated_at) ON upload_sessions TO relay_worker;

GRANT SELECT, INSERT ON upload_session_parts TO relay_app;
GRANT UPDATE (signed_count, last_signed_at, etag, size_bytes, verified_at) ON upload_session_parts TO relay_app;
GRANT SELECT ON upload_session_parts TO relay_worker;

GRANT SELECT, INSERT ON source_rights_grants TO relay_app;
GRANT UPDATE (revoked_at, revoked_by, revoke_reason) ON source_rights_grants TO relay_app;
GRANT SELECT ON source_rights_grants TO relay_worker;
